import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    ZIP_DIR.mkdir(parents=True, exist_ok=True)
    zip_path = DOWNLOAD_DIR / filename

    try:
        response = requests.get(url, verify=False, timeout=20)
        response.raise_for_status()
        with open(zip_path, 'wb') as f:
            f.write(response.content)
    except Exception as e:
        return (f"Error: Download failed - {e}", [])

    try:
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            zip_ref.extractall(ZIP_DIR)

        extracted_files = [f.name for f in ZIP_DIR.iterdir()]
        return ("Success: File extracted successfully", extracted_files)
    except Exception as e:
        return (f"Error: Extraction failed - {e}", [])

import requests
import pandas as pd
def task_func(url: str) -> pd.DataFrame:
    try:
        response = requests.get(url, timeout=5, verify=False)
        response.raise_for_status()
    except requests.RequestException as e:
        raise SystemError(f"Network-related issue: {e}")

    try:
        data = response.json()
        df = pd.DataFrame(data)
    except Exception as e:
        raise ValueError(f"Invalid JSON format or structure: {e}")

    return df

import ast
import requests
from bs4 import BeautifulSoup
def task_func(url):
    results = []
    try:
        response = requests.get(url, verify=False, timeout=10)
        response.raise_for_status()

        soup = BeautifulSoup(response.text, 'html.parser')
        scripts = soup.find_all('script')

        for script in scripts:
            content = script.string
            if content:
                content = content.strip()
                try:
                    evaluated = ast.literal_eval(content)
                    if isinstance(evaluated, dict):
                        results.append(evaluated)
                except (ValueError, SyntaxError, MemoryError):
                    continue

    except Exception:
        return []

    return results

import ipaddress
import requests
def task_func(ip_range, timeout):
    try:
        network = ipaddress.ip_network(ip_range, strict=False)
    except (ValueError, TypeError):
        raise ValueError("Invalid IP range provided.")

    active_ips = []
    for ip in network:
        try:
            url = f"http://{ip}"
            response = requests.get(url, timeout=timeout, verify=False)
            if response.status_code == 200:
                active_ips.append(str(ip))
        except requests.RequestException:
            continue

    return active_ips

